// src/lib.rs
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::RwLock;
use tokio::task::JoinHandle;
use tokio::time;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvictionReason {
    Expired,
    Lru,
    Memory,
}

struct CacheEntry<V> {
    value: Arc<V>,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,
}

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<Arc<dyn Fn(String, EvictionReason) + Send + Sync>>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_millis(60000),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_millis(5000),
            on_evict: None,
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

struct CacheInner<V> {
    entries: HashMap<String, CacheEntry<V>>,
    access_order: VecDeque<String>,
    current_memory: usize,
    stats: CacheStats,
}

pub struct LRUCache<V> {
    inner: Arc<RwLock<CacheInner<V>>>,
    config: Arc<CacheConfig>,
    eviction_handle: Arc<RwLock<Option<JoinHandle<()>>>>,
}

impl<V> LRUCache<V>
where
    V: 'static,
{
    pub fn new(config: CacheConfig) -> Self {
        Self {
            inner: Arc::new(RwLock::new(CacheInner {
                entries: HashMap::new(),
                access_order: VecDeque::new(),
                current_memory: 0,
                stats: CacheStats::default(),
            })),
            config: Arc::new(config),
            eviction_handle: Arc::new(RwLock::new(None)),
        }
    }

    pub async fn get(&self, key: &str) -> Option<Arc<V>> {
        let now = Instant::now();
        let mut inner = self.inner.write().await;

        let entry = inner.entries.get_mut(key)?;

        if now > entry.expires_at {
            let key_owned = key.to_string();
            drop(inner);
            self.delete_internal(&key_owned, EvictionReason::Expired).await;
            let mut inner = self.inner.write().await;
            inner.stats.misses += 1;
            return None;
        }

        entry.last_accessed = now;
        entry.access_count += 1;

        // Move to front
        if let Some(pos) = inner.access_order.iter().position(|k| k == key) {
            inner.access_order.remove(pos);
        }
        inner.access_order.push_front(key.to_string());

        inner.stats.hits += 1;
        Some(Arc::clone(&entry.value))
    }

    pub async fn put(&self, key: String, value: V, ttl: Option<Duration>, size: Option<usize>) {
        let value_arc = Arc::new(value);
        let size = size.unwrap_or_else(|| Self::estimate_size(&value_arc));
        let ttl = ttl.unwrap_or(self.config.default_ttl);

        let mut inner = self.inner.write().await;

        // Remove old entry's memory usage
        if let Some(old) = inner.entries.get(&key) {
            inner.current_memory -= old.size;
        }

        // Evict for memory
        while inner.current_memory + size > self.config.max_memory_bytes
            && !inner.access_order.is_empty()
        {
            if let Some(oldest) = inner.access_order.pop_back() {
                Self::delete_entry(&mut inner, &oldest, EvictionReason::Memory, &self.config);
            }
        }

        // Evict for max entries
        while inner.entries.len() >= self.config.max_entries && !inner.access_order.is_empty() {
            if let Some(oldest) = inner.access_order.pop_back() {
                Self::delete_entry(&mut inner, &oldest, EvictionReason::Lru, &self.config);
            }
        }

        let now = Instant::now();
        let entry = CacheEntry {
            value: value_arc,
            expires_at: now + ttl,
            size,
            last_accessed: now,
            access_count: 0,
        };

        inner.entries.insert(key.clone(), entry);
        inner.current_memory += size;

        // Move to front
        if let Some(pos) = inner.access_order.iter().position(|k| k == &key) {
            inner.access_order.remove(pos);
        }
        inner.access_order.push_front(key);
    }

    pub async fn delete(&self, key: &str, reason: EvictionReason) -> bool {
        self.delete_internal(key, reason).await
    }

    async fn delete_internal(&self, key: &str, reason: EvictionReason) -> bool {
        let mut inner = self.inner.write().await;
        Self::delete_entry(&mut inner, key, reason, &self.config)
    }

    fn delete_entry(
        inner: &mut CacheInner<V>,
        key: &str,
        reason: EvictionReason,
        config: &CacheConfig,
    ) -> bool {
        let entry = match inner.entries.remove(key) {
            Some(e) => e,
            None => return false,
        };

        inner.current_memory -= entry.size;
        inner.access_order.retain(|k| k != key);

        match reason {
            EvictionReason::Expired => inner.stats.expirations += 1,
            _ => inner.stats.evictions += 1,
        }

        if let Some(ref callback) = config.on_evict {
            callback(key.to_string(), reason);
        }

        true
    }

    pub async fn has(&self, key: &str) -> bool {
        let now = Instant::now();
        let inner = self.inner.read().await;

        match inner.entries.get(key) {
            Some(entry) if now <= entry.expires_at => true,
            Some(_) => {
                drop(inner);
                self.delete_internal(key, EvictionReason::Expired).await;
                false
            }
            None => false,
        }
    }

    pub async fn size(&self) -> usize {
        let inner = self.inner.read().await;
        inner.entries.len()
    }

    pub async fn memory_usage(&self) -> usize {
        let inner = self.inner.read().await;
        inner.current_memory
    }

    pub async fn get_stats(&self) -> CacheStats {
        let inner = self.inner.read().await;
        CacheStats {
            hits: inner.stats.hits,
            misses: inner.stats.misses,
            evictions: inner.stats.evictions,
            expirations: inner.stats.expirations,
            size: inner.entries.len(),
            memory: inner.current_memory,
        }
    }

    pub async fn clear(&self) {
        let mut inner = self.inner.write().await;
        let keys: Vec<String> = inner.entries.keys().cloned().collect();
        for key in keys {
            Self::delete_entry(&mut inner, &key, EvictionReason::Lru, &self.config);
        }
    }

    pub async fn start_eviction_loop(&self) {
        let mut handle = self.eviction_handle.write().await;
        if handle.is_some() {
            return;
        }

        let inner = Arc::clone(&self.inner);
        let config = Arc::clone(&self.config);
        let interval = config.eviction_check_interval;

        let task = tokio::spawn(async move {
            let mut ticker = time::interval(interval);
            loop {
                ticker.tick().await;
                Self::evict_expired_static(&inner, &config).await;
            }
        });

        *handle = Some(task);
    }

    pub async fn stop_eviction_loop(&self) {
        let mut handle = self.eviction_handle.write().await;
        if let Some(h) = handle.take() {
            h.abort();
        }
    }

    async fn evict_expired_static(
        inner: &Arc<RwLock<CacheInner<V>>>,
        config: &Arc<CacheConfig>,
    ) {
        let now = Instant::now();
        let expired: Vec<String> = {
            let inner_guard = inner.read().await;
            inner_guard
                .entries
                .iter()
                .filter(|(_, entry)| now > entry.expires_at)
                .map(|(k, _)| k.clone())
                .collect()
        };

        let mut inner_guard = inner.write().await;
        for key in expired {
            Self::delete_entry(&mut inner_guard, &key, EvictionReason::Expired, config);
        }
    }

    pub async fn keys(&self) -> Vec<String> {
        let inner = self.inner.read().await;
        inner.access_order.iter().cloned().collect()
    }

    pub async fn values(&self) -> Vec<Arc<V>> {
        let inner = self.inner.read().await;
        inner
            .access_order
            .iter()
            .filter_map(|k| inner.entries.get(k).map(|e| Arc::clone(&e.value)))
            .collect()
    }

    fn estimate_size(value: &V) -> usize {
        std::mem::size_of_val(value)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_basic_get_put() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_millis(100),
            ..Default::default()
        });

        cache.put("a".to_string(), "hello".to_string(), None, None).await;
        let val = cache.get("a").await;
        assert_eq!(val.as_deref().map(|s| s.as_str()), Some("hello"));
        assert_eq!(cache.size().await, 1);
    }

    #[tokio::test]
    async fn test_lru_eviction() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_millis(100),
            ..Default::default()
        });

        cache.put("a".to_string(), "hello".to_string(), None, None).await;
        cache.put("b".to_string(), "world".to_string(), None, None).await;
        cache.put("c".to_string(), "foo".to_string(), None, None).await;
        cache.put("d".to_string(), "bar".to_string(), None, None).await;

        assert!(!cache.has("a").await);
        assert!(cache.has("d").await);
    }

    #[tokio::test]
    async fn test_ttl_expiration() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_millis(100),
            ..Default::default()
        });

        cache.clear().await;
        cache
            .put(
                "x".to_string(),
                "temp".to_string(),
                Some(Duration::from_millis(50)),
                None,
            )
            .await;

        tokio::time::sleep(Duration::from_millis(80)).await;

        let val = cache.get("x").await;
        assert_eq!(val, None);
    }

    #[tokio::test]
    async fn test_access_order() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_millis(100),
            ..Default::default()
        });

        cache.clear().await;
        cache.put("1".to_string(), "one".to_string(), None, None).await;
        cache.put("2".to_string(), "two".to_string(), None, None).await;
        cache.put("3".to_string(), "three".to_string(), None, None).await;

        cache.get("1").await; // Access '1', making '2' the LRU
        cache.put("4".to_string(), "four".to_string(), None, None).await;

        assert!(!cache.has("2").await);
        assert!(cache.has("1").await);
    }

    #[tokio::test]
    async fn test_stats() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_millis(100),
            ..Default::default()
        });

        cache.put("a".to_string(), "hello".to_string(), None, None).await;
        cache.get("a").await;
        cache.get("b").await;

        let stats = cache.get_stats().await;
        assert!(stats.hits > 0);
        assert!(stats.misses > 0);
    }

    #[tokio::test]
    async fn test_eviction_loop() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 10,
            default_ttl: Duration::from_millis(50),
            eviction_check_interval: Duration::from_millis(30),
            ..Default::default()
        });

        cache.put("e1".to_string(), "val1".to_string(), None, None).await;
        cache.start_eviction_loop().await;

        tokio::time::sleep(Duration::from_millis(150)).await;

        assert!(!cache.has("e1").await);
        cache.stop_eviction_loop().await;
    }
}
